                .andExpect(jsonPath("$[0].destinationId", is(8)))
                .andExpect(jsonPath("$[0].destinationName", is("Athens")))
                .andExpect(jsonPath("$[0].destinationStatus", is("ACTIVE")))
                .andExpect(jsonPath("$[0].lowRatedCount", is(1)));
    }
