$destinationBody = @{
    name = "Santorini"
    country = "Greece"
    description = "idyllic Greek island with caldera views"
    category = "BEACH"
    status = "ACTIVE"
    rating = 4.8
    totalRatings = 250
    details = @{
        topAttractions = @("Oia sunset", "Red Beach")
